'use client';
import {useMemo,useState} from 'react';
export default function Financeiro(){const [period,setPeriod]=useState('2026-08');const data=useMemo(()=>({invoiced:38450,received:25670,pending:12780,costs:19530,profit:18920}),[period]);return <main style={{padding:32,fontFamily:'Arial',maxWidth:1200}}><h1>Financeiro</h1><p>Caixa, entradas, saídas, pagamentos e resultado por período.</p><label>Período: <input type="month" value={period} onChange={e=>setPeriod(e.target.value)}/></label><div style={{display:'grid',gridTemplateColumns:'repeat(auto-fit,minmax(180px,1fr))',gap:16,marginTop:24}}>{[['Faturado',data.invoiced],['Recebido',data.received],['Por receber',data.pending],['Custos',data.costs],['Resultado',data.profit]].map(([l,v])=><div style={{padding:20,border:'1px solid #ddd',borderRadius:12}} key={String(l)}><small>{l}</small><h2>€{Number(v).toLocaleString('pt-PT',{minimumFractionDigits:2})}</h2></div>)}</div><h2 style={{marginTop:30}}>Folha de caixa</h2><p>As entradas, saídas, despesas e pagamentos ficam associados às obras e clientes.</p></main>}
